import { NO_COPY_CLASS } from "@hunt/copy-to-clipboard";
import { HorizontalDivider, useColorAssist } from "@hunt/puzzle-components";
import { cn } from "@hunt/styled-ui";
import React from "react";
import Nonogram from "./Nonogram";
import { gridImages } from "./get_images";
import {
  NONOGRAM_1_LEFT,
  NONOGRAM_1_TOP,
  NONOGRAM_2_TOP,
  NONOGRAM_2_LEFT,
  NONOGRAM_3_TOP,
  NONOGRAM_3_LEFT,
  NONOGRAM_4_TOP,
  NONOGRAM_4_LEFT,
  NONOGRAM_5_TOP,
  NONOGRAM_5_LEFT,
} from "./nonogram_clues";

const NonogramWrapper = () => {
  const [colorAssistEnabled, setColorAssistEnabled] = useColorAssist();

  return (
    <div className="flex flex-col items-center">
      {/* Color assist accessibility toggle */}
      <div className={cn("flex items-center space-x-2 mb-4", NO_COPY_CLASS)}>
        <label className="flex items-center space-x-2 cursor-pointer">
          <input
            type="checkbox"
            checked={colorAssistEnabled}
            onChange={() => {
              setColorAssistEnabled(!colorAssistEnabled);
            }}
            className="h-4 w-4 rounded border-gray-300"
            aria-label="Enable color assist mode to show color legend with shapes"
          />
          <span>Show color legend</span>
        </label>
      </div>

      <div className="flex flex-col gap-8 items-end">
        <Nonogram
          top={NONOGRAM_1_TOP}
          left={NONOGRAM_1_LEFT}
          colorblindFriendly={colorAssistEnabled}
        />
        <Nonogram
          top={NONOGRAM_2_TOP}
          left={NONOGRAM_2_LEFT}
          copyToClipboardLeftMargin={1}
          colorblindFriendly={colorAssistEnabled}
        />
        <Nonogram
          top={NONOGRAM_3_TOP}
          left={NONOGRAM_3_LEFT}
          copyToClipboardLeftMargin={1}
          colorblindFriendly={colorAssistEnabled}
        />
        <Nonogram
          top={NONOGRAM_4_TOP}
          left={NONOGRAM_4_LEFT}
          copyToClipboardLeftMargin={4}
          colorblindFriendly={colorAssistEnabled}
        />
        <Nonogram
          top={NONOGRAM_5_TOP}
          left={NONOGRAM_5_LEFT}
          colorblindFriendly={colorAssistEnabled}
        />
      </div>
      <HorizontalDivider copyToClipboardNumCols={25} />
      <table className="m-2">
        {gridImages.map((row, rowIndex) => (
          <tr key={rowIndex}>
            {row.map((image, colIndex) => (
              <td key={colIndex}>
                <a href={image} target="_blank" rel="noopener noreferrer">
                  <img alt="" src={image} width="96" />
                </a>
              </td>
            ))}
          </tr>
        ))}
      </table>
    </div>
  );
};

export default NonogramWrapper;
