import { cn } from "@hunt/styled-ui";
import React from "react";

type NonogramClueCell = {
  content?: string;
  className?: string;
};

// Map color classes to shapes for colorblind accessibility
const getShapeForColor = (className?: string): string => {
  if (!className) return "";

  // Grid 1 colors - check for hex colors in className
  if (className.includes("#fdb402")) {
    return "●"; // circle
  }
  if (className.includes("#fe8b0d")) {
    return "▲"; // triangle
  }
  if (className.includes("#ed6a31")) {
    return "■"; // square
  }

  // Grid 2 colors
  if (className.includes("#91de98")) {
    return "●"; // circle
  }
  if (className.includes("#61ae63")) {
    return "▲"; // triangle
  }
  if (className.includes("#447a3b")) {
    return "■"; // square
  }
  if (className.includes("#2c462a")) {
    return "◆"; // diamond
  }

  // Grid 3 colors
  if (className.includes("#fbd27f")) {
    return "●"; // circle
  }
  if (className.includes("#fa7936")) {
    return "▲"; // triangle
  }
  if (className.includes("#bd3700")) {
    return "■"; // square
  }

  // Grid 4 colors
  if (className.includes("#e0dfdf")) {
    return "●"; // circle
  }
  if (className.includes("#bcbdc1")) {
    return "▲"; // triangle
  }
  if (className.includes("#ffa72b")) {
    return "■"; // square
  }
  if (className.includes("#7c2e21")) {
    return "◆"; // diamond
  }

  // Grid 5 colors
  if (className.includes("#fed40a")) {
    return "●"; // circle
  }
  if (className.includes("#fe8d03")) {
    return "▲"; // triangle
  }
  if (className.includes("#8c5840")) {
    return "■"; // square
  }

  // Black
  if (className.includes("bg-black")) {
    return "★"; // diamond
  }

  return "";
};

const NonogramCell = ({
  content,
  className,
  showShape = false,
}: NonogramClueCell & { showShape?: boolean }) => {
  const shape = showShape ? getShapeForColor(className) : "";
  return (
    <td
      className={cn(
        "text-center font-mono font-bold text-sm min-w-8 min-h-8 w-8 h-8 p-1 bg-white",
        shape && "text-xs p-0.5",
        className,
      )}
    >
      {content}
      {shape && <span className="ml-[3px] text-sm">{shape}</span>}
    </td>
  );
};

type NonogramProps = {
  top?: NonogramClueCell[][];
  left?: NonogramClueCell[][];
  body?: NonogramClueCell[][];
  copyToClipboardLeftMargin?: number;
  colorblindFriendly?: boolean;
};

const Nonogram = ({
  top,
  left,
  body,
  copyToClipboardLeftMargin,
  colorblindFriendly = false,
}: NonogramProps) => {
  // Calculate the width of the top clue area (max number of columns for top clues).
  const topClueDepth =
    top?.reduce((max, clue) => Math.max(max, clue.length), 0) ?? 0;
  // Calculate the height of the left clue area (max number of rows for left clues).
  const leftClueDepth =
    left?.reduce((max, clue) => Math.max(max, clue.length), 0) ?? 0;

  const leftMargin = copyToClipboardLeftMargin ?? 0;

  // Extract hex code from className (e.g., "bg-[#fdb402]" -> "#fdb402")
  const extractHex = (className: string): string => {
    const regex = /#[0-9a-fA-F]{6}/;
    const match = regex.exec(className);
    return match ? match[0] : "";
  };

  // Extract unique colors from clues for the legend
  const getUniqueColors = (): {
    className: string;
    shape: string;
    hex: string;
  }[] => {
    const colorSet = new Set<string>();
    const allClues = [...(top ?? []), ...(left ?? [])];

    allClues.forEach((clueArray) => {
      clueArray.forEach((cell) => {
        if (cell.className) {
          colorSet.add(cell.className);
        }
      });
    });

    return Array.from(colorSet)
      .map((className) => ({
        className,
        shape: getShapeForColor(className),
        hex:
          extractHex(className) ||
          (className.includes("bg-black") ? "#000000" : ""),
      }))
      .filter((item) => item.shape !== "" && item.hex !== "") // Only include colors that have shapes and hex codes
      .sort((a, b) => {
        // Sort by sum of RGB values (lightness) - larger sums are lighter
        const hexA = a.hex.replace("#", "");
        const hexB = b.hex.replace("#", "");
        const rA = parseInt(hexA.substring(0, 2), 16);
        const gA = parseInt(hexA.substring(2, 4), 16);
        const bA = parseInt(hexA.substring(4, 6), 16);
        const rB = parseInt(hexB.substring(0, 2), 16);
        const gB = parseInt(hexB.substring(2, 4), 16);
        const bB = parseInt(hexB.substring(4, 6), 16);
        const sumA = rA + gA + bA;
        const sumB = rB + gB + bB;
        return sumB - sumA; // Descending order (light to dark)
      });
  };

  const uniqueColors = colorblindFriendly ? getUniqueColors() : [];

  return (
    <div className="flex flex-col items-start gap-2">
      {/* CSS to show left margin columns when copying */}
      {leftMargin > 0 && (
        <style>{`
          .copying .copy-margin-cell {
            display: table-cell !important;
          }
        `}</style>
      )}

      {/* Legend for colorblind friendly mode */}
      {colorblindFriendly && uniqueColors.length > 0 && (
        <div className="border border-black px-3 py-2 mb-2 w-fit ml-auto">
          <div className="flex flex-col gap-2">
            {uniqueColors.map(({ shape, hex }, index) => (
              <div key={index} className="flex items-center gap-2">
                <div
                  className="w-4 h-4 rounded"
                  style={{ backgroundColor: hex }}
                />
                <span className="font-mono">{shape}</span>
                <span className="font-mono">{hex}</span>
              </div>
            ))}
          </div>
        </div>
      )}

      <table className="max-w-fit">
        <tbody>
          {/* Render the top clue rows. */}
          {Array.from({ length: topClueDepth }).map((_, clueRow) => (
            <tr key={`top-row-${clueRow}`}>
              {/* Empty columns for copy to clipboard left margin (only visible when copying) */}
              {leftMargin > 0 &&
                Array.from({ length: leftMargin }).map((_, i) => (
                  <td
                    key={`copy-margin-top-${i}-${clueRow}`}
                    className="copy-margin-cell hidden"
                  />
                ))}
              {/* Empty cells for the top-left corner. */}
              {Array.from({ length: leftClueDepth }).map((_, i) => (
                <td key={`corner-${i}-${clueRow}`} />
              ))}
              {/* Display the top clues. */}
              {top?.map((clueArray, col) => {
                const index = clueArray.length - topClueDepth + clueRow;
                return index >= 0 ? (
                  <NonogramCell
                    content={clueArray[index].content}
                    className={cn(
                      "border border-black",
                      clueArray[index].className,
                    )}
                    showShape={colorblindFriendly}
                  />
                ) : (
                  <td key={`top-empty-${col}-${clueRow}`} />
                );
              })}
            </tr>
          ))}
          {/* Render the main grid rows (with left clues). */}
          {(body ?? left)?.map((clueArray, row) => (
            <tr key={`nonogram-row-${row}`}>
              {/* Empty columns for copy to clipboard left margin (only visible when copying) */}
              {leftMargin > 0 &&
                Array.from({ length: leftMargin }).map((_, i) => (
                  <td
                    key={`copy-margin-${i}-${row}`}
                    className="copy-margin-cell hidden"
                  />
                ))}
              {/* Left clues for this row. */}
              {Array.from({ length: leftClueDepth }).map((_, clueCell) => {
                const index = clueArray.length - leftClueDepth + clueCell;
                return index >= 0 ? (
                  <NonogramCell
                    content={clueArray[index].content}
                    className={cn(
                      "border border-black",
                      clueArray[index].className,
                    )}
                    showShape={colorblindFriendly}
                  />
                ) : (
                  <td key={`left-empty-${row}-${clueCell}`} />
                );
              })}
              {/* The actual nonogram grid cells, which default to empty. */}
              {/* TODO: Support filled cells when implementing solution. */}
              {(body ?? top)?.map((_, col) => {
                let borderStyling = "border border-black";
                if (col === 0) {
                  borderStyling += " border-l-4";
                }
                if (col === (body ?? top ?? []).length - 1) {
                  borderStyling += " border-r-4";
                }
                if (row === 0) {
                  borderStyling += " border-t-4";
                }
                if (row === (body ?? left ?? []).length - 1) {
                  borderStyling += " border-b-4";
                }
                // Make every 5th vertical gridline thicker
                if (col > 0 && col % 5 === 0) {
                  borderStyling += " border-l-4";
                }
                // Make every 5th horizontal gridline thicker
                if (row > 0 && row % 5 === 0) {
                  borderStyling += " border-t-4";
                }

                return (
                  <NonogramCell
                    key={`nonogram-cell-${row}-${col}`}
                    content={body?.[row][col]?.content}
                    className={cn(borderStyling, body?.[row][col]?.className)}
                    showShape={colorblindFriendly}
                  />
                );
              })}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default Nonogram;
